  {
   "codice": "extends RefCounted


func run() -> float:
	var jump_height: float = 50.0
	var jump_time_to_peak: float = 1.0
	var gravity: float = (2.0 * jump_height) / (jump_time_to_peak * jump_time_to_peak)
	return gravity
",
   "domanda": "Quanto vale `gravity`?",
   "spiegazione": "Con un'altezza di `50.0` e un tempo di risalita di `1.0`, la formula calcola `(2.0 * 50.0) / (1.0 * 1.0)`, che restituisce `100.0`."
  },
  {
   "codice": "extends RefCounted


func run() -> float:
	var jump_height: float = 100.0
	var jump_time_to_peak: float = 0.5
	var jump_velocity: float = -(2.0 * jump_height) / jump_time_to_peak
	return jump_velocity
",
   "domanda": "Quanto vale `jump_velocity`?",
   "spiegazione": "La formula della spinta verso l'alto include il segno meno per muoversi verso l'alto nello spazio 2D: `-(2.0 * 100.0) / 0.5` calcola `-400.0`."
  },
  {
   "codice": "extends RefCounted


func run() -> float:
	var velocity_y: float = -300.0
	var jump_released: bool = true
	if jump_released and velocity_y < 0.0:
		velocity_y *= 0.5
	return velocity_y
",
   "domanda": "Quanto vale `velocity_y` alla fine?",
   "spiegazione": "Il salto variabile (cut jump) dimezza la velocità verticale se il tasto viene rilasciato mentre il personaggio sta ancora salendo (`velocity_y < 0.0`). Essendo `-300.0`, moltiplicato per `0.5` diventa `-150.0`."
  },
  {
   "codice": "extends RefCounted


func run() -> float:
	var velocity_y: float = 700.0
	var max_fall_speed: float = 600.0
	if velocity_y > max_fall_speed:
		velocity_y = max_fall_speed
	return velocity_y
",
   "domanda": "Quanto vale `velocity_y` alla fine?",
   "spiegazione": "La velocità di caduta supera il limite massimo consentito (`700.0 > 600.0`), quindi la condizione è vera e `velocity_y` viene limitata esattamente a `600.0`."
  },
