   "codice": "extends RefCounted


func run() -> float:
	var velocity_y: float = 100.0
	var gravity: float = 500.0
	var delta: float = 0.02
	velocity_y += gravity * delta
	return velocity_y
",
   "domanda": "Quanto vale `velocity_y` alla fine?",
